<?php
function bizLabel(array $p): string {return $p['ko'].' / '.$p['en'].' '.$p['pack'];}
function bizConsigned(string $code,string $category): bool {return ($code==='OK'&&$category!=='kimchi')||($code==='PT'&&$category!=='kimchi');}
function bizRate(mixed $v): int {if(!is_string($v)||!preg_match('/^\d{1,3}(?:\.\d{1,2})?$/D',$v)||(float)$v>100)throw new InvalidArgumentException('할인율은 0~100%입니다.');return (int)round((float)$v*100);}
function bizPrice(array $client,array $p): int {
 $price=query('SELECT cents FROM biz_prices WHERE client_id=? AND product_id=?',[$client['id'],$p['id']])->fetchColumn();
 if($client['code']==='OK'&&$p['category']!=='kimchi')$price=$p['retail_cents'];
 elseif(!$client['code'])$price=$p['retail_cents'];
 if($price===false||$price===null)throw new InvalidArgumentException(bizLabel($p).' 단가를 먼저 등록하세요.');return (int)$price;
}
function bizAvailable(int $id): int {return (int)query('SELECT delivered-COALESCE((SELECT SUM(qty) FROM biz_sales WHERE delivery_id=d.id),0)-COALESCE((SELECT SUM(qty) FROM biz_returns WHERE delivery_id=d.id),0) FROM biz_deliveries d WHERE id=?',[$id])->fetchColumn();}
function bizClosed(int $client,string $day): void {if(query("SELECT invoice_id FROM biz_periods WHERE client_id=? AND ? BETWEEN start_day AND end_day",[$client,$day])->fetchColumn())throw new InvalidArgumentException('이미 정산한 기간입니다. 추가 판매는 인보이스 정정 절차가 필요합니다.');}
function bizIssue(int $client,string $start,string $end,string $kind,?string $delivery=null): int {
 if($start>$end)throw new InvalidArgumentException('기간을 확인하세요.');$c=query('SELECT * FROM biz_clients WHERE id=?',[$client])->fetch();if(!$c)throw new InvalidArgumentException('거래처를 확인하세요.');
 if($delivery===null&&($prior=query('SELECT invoice_id FROM biz_periods WHERE client_id=? AND kind=? AND start_day=? AND end_day=?',[$client,$kind,$start,$end])->fetchColumn()))return (int)$prior;
 $rows=query('SELECT s.*,p.category,p.ko,p.en,p.pack FROM biz_sales s JOIN biz_deliveries d ON d.id=s.delivery_id JOIN biz_products p ON p.id=d.product_id WHERE d.client_id=? AND s.day BETWEEN ? AND ? AND s.invoice_id IS NULL'.($delivery?' AND d.batch_key='.db()->quote($delivery):'')." ORDER BY p.id,s.id",[$client,$start,$end])->fetchAll();
 $rows=array_values(array_filter($rows,fn($r)=>($c['code']==='PT'&&$kind==='consigned')||($kind==='direct'?!bizConsigned((string)$c['code'],$r['category']):bizConsigned((string)$c['code'],$r['category']))));if(!$rows)throw new InvalidArgumentException('정산할 미청구 판매가 없습니다.');
 $lines=[];$net=$tax=$discount=0;
 foreach($rows as $r){if($r['staff_qty']&&$c['staff_discount_bp']===null)throw new InvalidArgumentException('직원 판매 할인율을 먼저 등록하세요.');$bp=$c['code']==='OK'&&$r['category']!=='kimchi'?2000:(int)$r['discount_bp'];$key=$r['en'].'|'.$r['pack'].'|'.$r['cents'].'|'.$bp;if(!isset($lines[$key]))$lines[$key]=['ko'=>$r['ko'],'en'=>$r['en'],'pack'=>$r['pack'],'qty'=>0,'staff'=>0,'unit'=>(int)$r['cents'],'bp'=>$bp,'taxable'=>$r['category']!=='kimchi','discount'=>0,'net'=>0,'hst'=>0];$lines[$key]['qty']+=(int)$r['qty'];$lines[$key]['staff']+=(int)$r['staff_qty'];}
 $taxable=0;foreach($lines as &$l){$base=$l['qty']*$l['unit'];$cut=(int)round($base*$l['bp']/10000)+(int)round($l['staff']*$l['unit']*(10000-$l['bp'])/10000*(int)($c['staff_discount_bp']??0)/10000);$l['discount']=$cut;$l['net']=$base-$cut;$discount+=$cut;$net+=$l['net'];if($l['taxable']){$taxable+=$l['net'];$nextTax=(int)round($taxable*13/100);$l['hst']=$nextTax-$tax;$tax=$nextTax;}}unset($l);
 if(count($lines)>34)throw new InvalidArgumentException('한 페이지에 담을 품목이 너무 많습니다. 기간을 나누어 발행하세요.');
 $seller=query('SELECT * FROM biz_settings WHERE id=1')->fetch();if(!$seller['address']||!$seller['gst'])throw new InvalidArgumentException('인보이스 발행 전에 사업자 주소와 GST/HST 번호를 등록하세요.');
 $snapshot=['client'=>$c,'seller'=>$seller,'lines'=>array_values($lines),'net'=>$net,'hst'=>$tax,'discount'=>$discount,'total'=>$net+$tax];
 query('INSERT INTO biz_invoices (client_id,issued,period_start,period_end,kind,snapshot,total_cents,created_by,mail_state) VALUES (?,?,?,?,?,?,?,?,?)',[$client,date('Y-m-d'),$start,$end,$kind,json_encode($snapshot,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),$net+$tax,$_SESSION['user_id']??null,in_array($c['code'],['OK','PT'])?'pending':'manual']);$id=(int)db()->lastInsertId();
 foreach($rows as $r)query('UPDATE biz_sales SET invoice_id=? WHERE id=? AND invoice_id IS NULL',[$id,$r['id']]);
 if($delivery===null)query('INSERT INTO biz_periods VALUES (?,?,?,?,?)',[$client,$kind,$start,$end,$id]);return $id;
}
function bizAction(string $action): never {
 $next='biz';db()->beginTransaction();try{
 if($action==='biz_product'){$id=positiveInt($_POST['id']??0,1,PHP_INT_MAX);query('UPDATE biz_products SET ko=?,en=?,retail_cents=? WHERE id=?',[textfield($_POST,'ko',100,true),textfield($_POST,'en',100,true),cents($_POST['retail']??''),$id]);$next='biz-products';}
 elseif($action==='biz_price'){query('INSERT INTO biz_prices VALUES (?,?,?) ON DUPLICATE KEY UPDATE cents=VALUES(cents)',[positiveInt($_POST['client_id']??0,1,PHP_INT_MAX),positiveInt($_POST['product_id']??0,1,PHP_INT_MAX),cents($_POST['price']??'')]);$next='biz-products';}
 elseif($action==='biz_client'){$id=positiveInt($_POST['id']??0,0,PHP_INT_MAX);$name=textfield($_POST,'name',150,true);$email=textfield($_POST,'email',150);if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))throw new InvalidArgumentException('이메일 주소를 확인하세요.');$values=[$name,$email,textfield($_POST,'address',500),($_POST['staff_discount']??'')===''?null:bizRate($_POST['staff_discount'])];if($id)query('UPDATE biz_clients SET name=?,email=?,address=?,staff_discount_bp=?,version=version+1 WHERE id=?',[...$values,$id]);else query('INSERT INTO biz_clients (name,email,address,staff_discount_bp) VALUES (?,?,?,?)',$values);$next='biz-clients';}
 elseif($action==='biz_plan'){$client=positiveInt($_POST['client_id']??0,1,PHP_INT_MAX);$day=validDate(textfield($_POST,'day',10,true));if(!query('SELECT id FROM biz_clients WHERE id=?',[$client])->fetch())throw new InvalidArgumentException('거래처를 선택하세요.');$key=textfield($_POST,'request_key',32,true);if(!preg_match('/^[a-f0-9]{32}$/D',$key))throw new InvalidArgumentException('화면을 새로 여세요.');foreach($_POST['qty']??[] as $pid=>$q){$qty=positiveInt($q,0,10000);if(!$qty)continue;$p=query('SELECT * FROM biz_products WHERE id=? AND active=1',[(int)$pid])->fetch();if(!$p)throw new InvalidArgumentException('제품을 확인하세요.');$k=substr(hash('sha256',$key.'|'.$pid),0,32);if(!query('SELECT id FROM biz_deliveries WHERE request_key=?',[$k])->fetch())query('INSERT INTO biz_deliveries (client_id,product_id,day,batch_key,planned,request_key,created_by,fulfillment,discount_bp) VALUES (?,?,?,?,?,?,?,?,?)',[$client,$pid,$day,$key,$qty,$k,$_SESSION['user_id'],optionalChoice($_POST,'fulfillment',['delivery','pickup'])?:'delivery',bizRate($_POST['discount']??'0')]);}$next='biz-production';}
 elseif($action==='biz_deliver'){$id=positiveInt($_POST['id']??0,1,PHP_INT_MAX);$d=query('SELECT d.*,p.category,p.ko,p.en,p.pack,p.retail_cents FROM biz_deliveries d JOIN biz_products p ON p.id=d.product_id WHERE d.id=? FOR UPDATE',[$id])->fetch();if(!$d||$d['sent'])throw new InvalidArgumentException('이미 납품했거나 없는 계획입니다.');$qty=positiveInt($_POST['delivered']??0,1,10000);$c=query('SELECT * FROM biz_clients WHERE id=?',[$d['client_id']])->fetch();bizClosed((int)$c['id'],$d['day']);$price=bizPrice($c,[...$d,'id'=>$d['product_id']]);query('UPDATE biz_deliveries SET sent=1,delivered=?,version=version+1 WHERE id=?',[$qty,$id]);if(!bizConsigned((string)$c['code'],$d['category'])){query('INSERT INTO biz_sales (delivery_id,day,qty,cents,discount_bp,request_key) VALUES (?,?,?,?,?,?)',[$id,$d['day'],$qty,$price,bizRate($_POST['discount']??(string)($d['discount_bp']/100)),bin2hex(random_bytes(16))]);if($c['code']==='PT'){$next='biz-invoices';}elseif(!(int)query("SELECT COUNT(*) FROM biz_deliveries d JOIN biz_products p ON p.id=d.product_id WHERE d.batch_key=? AND d.sent=0".(in_array($c['code'],['OK','PT'])?" AND p.category='kimchi'":''),[$d['batch_key']])->fetchColumn()){$invoice=bizIssue((int)$c['id'],$d['day'],$d['day'],'direct',$d['batch_key']);$next='biz-invoice&id='.$invoice;}else $next='biz';}else $next='biz-results';}
 elseif($action==='biz_result'){$id=positiveInt($_POST['id']??0,1,PHP_INT_MAX);$d=query('SELECT d.*,p.category,p.ko,p.en,p.pack,p.retail_cents FROM biz_deliveries d JOIN biz_products p ON p.id=d.product_id WHERE d.id=? AND d.sent=1 FOR UPDATE',[$id])->fetch();if(!$d)throw new InvalidArgumentException('납품을 확인하세요.');$c=query('SELECT * FROM biz_clients WHERE id=?',[$d['client_id']])->fetch();if(!bizConsigned((string)$c['code'],$d['category']))throw new InvalidArgumentException('직매출은 납품 시 기록합니다.');$day=validDate(textfield($_POST,'day',10,true));if($day<$d['day'])throw new InvalidArgumentException('판매일은 납품일 이후여야 합니다.');bizClosed((int)$c['id'],$day);$q=positiveInt($_POST['sold']??0,0,10000);$back=positiveInt($_POST['returned']??0,0,10000);$staff=positiveInt($_POST['staff']??0,0,$q);if($q+$back>bizAvailable($id))throw new InvalidArgumentException('판매·반품 수량이 남은 재고보다 많습니다.');$key=textfield($_POST,'request_key',32,true);if(!preg_match('/^[a-f0-9]{32}$/D',$key))throw new InvalidArgumentException('화면을 새로 여세요.');if(query('SELECT id FROM biz_sales WHERE request_key=? UNION SELECT id FROM biz_returns WHERE request_key=?',[$key,$key])->fetch())throw new InvalidArgumentException('이미 기록했습니다.');if($q)query('INSERT INTO biz_sales (delivery_id,day,qty,staff_qty,cents,request_key) VALUES (?,?,?,?,?,?)',[$id,$day,$q,$staff,bizPrice($c,[...$d,'id'=>$d['product_id']]),$key]);if($back)query('INSERT INTO biz_returns (delivery_id,day,qty,request_key) VALUES (?,?,?,?)',[$id,$day,$back,$key]);query('INSERT INTO biz_reports VALUES (?,?,?) ON DUPLICATE KEY UPDATE day=day',[$c['id'],$id,$day]);$next='biz-results';}
 elseif($action==='biz_settle'){require_once __DIR__.'/business-mail.php';$checkClient=positiveInt($_POST['client_id']??0,1,PHP_INT_MAX);$checkStart=validDate(textfield($_POST,'start',10,true));$checkEnd=validDate(textfield($_POST,'end',10,true));if(!bizReportsComplete($checkClient,$checkStart,$checkEnd))throw new InvalidArgumentException('기간 내 일일 판매·0개 판매·반품 마감을 먼저 완료하세요.');$id=bizIssue(positiveInt($_POST['client_id']??0,1,PHP_INT_MAX),validDate(textfield($_POST,'start',10,true)),validDate(textfield($_POST,'end',10,true)),'consigned');$next='biz-invoice&id='.$id;}
 elseif($action==='biz_staff'){$id=positiveInt($_POST['id']??0,1,PHP_INT_MAX);$sale=query('SELECT s.*,c.code FROM biz_sales s JOIN biz_deliveries d ON d.id=s.delivery_id JOIN biz_clients c ON c.id=d.client_id WHERE s.id=? FOR UPDATE',[$id])->fetch();if(!$sale||$sale['invoice_id']||$sale['code']!=='PT')throw new InvalidArgumentException('발행 전 Popularitea 판매만 직원 수량을 수정할 수 있습니다.');query('UPDATE biz_sales SET staff_qty=? WHERE id=?',[positiveInt($_POST['staff']??0,0,(int)$sale['qty']),$id]);$next='biz-results';}
 elseif($action==='biz_payment'){$id=positiveInt($_POST['id']??0,1,PHP_INT_MAX);$i=query('SELECT * FROM biz_invoices WHERE id=? FOR UPDATE',[$id])->fetch();if(!$i)throw new InvalidArgumentException('인보이스를 확인하세요.');$key=textfield($_POST,'request_key',32,true);if(!preg_match('/^[a-f0-9]{32}$/D',$key))throw new InvalidArgumentException('화면을 새로 여세요.');if(!query('SELECT id FROM biz_payments WHERE request_key=?',[$key])->fetch()){$amount=cents($_POST['amount']??'');$paid=(int)query('SELECT COALESCE(SUM(cents),0) FROM biz_payments WHERE invoice_id=?',[$id])->fetchColumn();if(!$amount||$paid+$amount>(int)$i['total_cents'])throw new InvalidArgumentException('남은 금액을 확인하세요.');$method=textfield($_POST,'method',20,true);if(!in_array($method,['cash','etransfer'],true))throw new InvalidArgumentException('수금 방법을 확인하세요.');query('INSERT INTO biz_payments (invoice_id,day,cents,method,request_key,created_by) VALUES (?,?,?,?,?,?)',[$id,validDate(textfield($_POST,'day',10,true)),$amount,$method,$key,$_SESSION['user_id']]);}$next='biz-invoice&id='.$id;}
 elseif($action==='biz_queue'){$id=positiveInt($_POST['id']??0,1,PHP_INT_MAX);$i=query('SELECT * FROM biz_invoices WHERE id=? FOR UPDATE',[$id])->fetch();if(!$i||$i['mail_state']==='sending')throw new InvalidArgumentException('인보이스 또는 현재 발송 상태를 확인하세요.');query("UPDATE biz_invoices SET mail_state='pending',mail_error='' WHERE id=?",[$id]);$next='biz-invoice&id='.$id;}
 elseif($action==='biz_settings'){$email=textfield($_POST,'email',150);if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))throw new InvalidArgumentException('발신 이메일을 확인하세요.');query('UPDATE biz_settings SET seller=?,address=?,gst=?,email=? WHERE id=1',[textfield($_POST,'seller',150,true),textfield($_POST,'address',500),textfield($_POST,'gst',100),$email]);$next='biz-clients';}
 else throw new InvalidArgumentException('업무를 확인하세요.');
 query('INSERT INTO biz_events (actor_id,kind,detail) VALUES (?,?,?)',[$_SESSION['user_id'],$action,json_encode(['input'=>array_diff_key($_POST,['csrf'=>1])],JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR)]);db()->commit();
 }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}
 $_SESSION['flash']='저장했습니다.';redirect('/?page='.$next);
}
